import{_ as t,o as a,c as o,aw as i}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Монорепозиторий","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/architecture/concepts/monorepository.md","filePath":"wiki/dev-commit/theory/architecture/concepts/monorepository.md"}'),r={name:"wiki/dev-commit/theory/architecture/concepts/monorepository.md"};function l(c,e,s,n,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="монорепозитории" tabindex="-1">Монорепозиторий <a class="header-anchor" href="#монорепозитории" aria-label="Permalink to &quot;Монорепозиторий&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Монорепозиторий</strong> - архитектурная концепция, при котрой код множества подпроектов хранится в одном и том же репозитории</li><li>Вместо управления несколькими репозиториями вы храните все изолированные части кода внутри одного репозитория</li><li>«Изолированный» - означает, что архитектура монорепозитория не имеет ничего общего с монолитными приложениями</li><li>Можно хранить много видов логических приложений внутри одного репозитория, например: веб-сайт и его приложение iOS</li></ul></div><h2 id="инструменты-для-монорепозиториев" tabindex="-1">Инструменты для монорепозиториев <a class="header-anchor" href="#инструменты-для-монорепозиториев" aria-label="Permalink to &quot;Инструменты для монорепозиториев&quot;">​</a></h2><h3 id="nx" tabindex="-1">NX <a class="header-anchor" href="#nx" aria-label="Permalink to &quot;NX&quot;">​</a></h3><ul><li><a href="https://nx.dev/" target="_blank" rel="noreferrer">https://nx.dev/</a></li><li>Система сборки, оптимизированная для монорепозиториев, с архитектурным пониманием на основе ИИ и расширенными возможностями CI</li></ul><h3 id="lage" tabindex="-1">Lage <a class="header-anchor" href="#lage" aria-label="Permalink to &quot;Lage&quot;">​</a></h3><ul><li><a href="https://microsoft.github.io/lage/" target="_blank" rel="noreferrer">https://microsoft.github.io/lage/</a></li><li>Оркестратор задач для JS/TS-монорепозиториев: строит граф зависимостей между пакетами, запускает скрипты параллельно и с кэшированием (аналог идеи «pipeline» для <code>workspaces</code>).</li><li>Подходит, когда нужно ускорить CI и локальные сборки без смены менеджера пакетов — конфигурация через <code>lage.config.js</code> и привычные <code>package.json</code> scripts.</li></ul>',7)])])}const u=t(r,[["render",l]]);export{m as __pageData,u as default};
